package org.kanger.storage.dumb2;
import java.util.*;import java.nio.file.*;import org.kanger.*;
import org.kanger.storage.dumb2.ContextNativeCandidateLeaseMatrix.Fixture;
public final class ContextMultivariablePublicationRunner {
 static int checks;static final String RULE="!@u @v p(u)&&q(v)->r(u);";static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static ContextSignedModelRequest req(String s){return new ContextSignedModelRequest(s,Collections.emptyMap());}static Set<String> primary(Fixture f)throws Exception{return ContextNativeCommitGuardMatrix.primary(f);}
 public static void main(String[] args){try{Path d=Files.createTempDirectory("multivariable-write-");System.setProperty("user.home",d.toString());
  try(Fixture f=new Fixture(d,"Multi")){String[] console=ContextAutomaticModelMatrix.console(f.mind,"ctx candidate model write \""+RULE+"\"\n");require(console[0].contains("MODEL WRITE: PUBLISHED")&&console[1].trim().isEmpty(),"actual Console first independent-variable rule publication");}
  try(Fixture f=new Fixture(d,"Multi")){require(primary(f).equals(Collections.singleton(RULE)),"durable original only, no model truth table saved as facts");String[] follow=ContextAutomaticModelMatrix.console(f.mind,"!p(1);\n!q(2);\n?r(1);\n");require(follow[1].trim().isEmpty(),"ordinary native follow-up with DISTINCT named values through actual Console");require(follow[0].contains("Result: TRUE"),"cross-variable actual Console derives r(1) from p(1),q(2)");}
  try(Fixture f=new Fixture(d,"Three")){String s="!@u @v @w p(u)&&q(v)&&r(w)->s(u);";long before=f.db.getRevision();ContextSignedModelPublication r=f.db.publishSignedModelCandidate(f.mind,req(s));require(r.status==ContextSignedModelPublication.Status.PUBLISHED,"three-variable native profile now completes with full model audit");require(primary(f).equals(Collections.singleton(s))&&f.db.getRevision()>before,"only complete three-variable row published");}
  ContextNativeCandidateLeaseMatrix.create(d,"Facts","!p(1);!q(2);");ContextNativeCandidateLeaseMatrix.create(d,"Negative","!~r(1);");
  try(Fixture f=new Fixture(d,"Rejected")){f.db.connectContext("Facts");f.db.connectContext("Negative");long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,req(RULE));require(no.status==ContextSignedModelPublication.Status.REFUTED&&no.evidence!=null,no.reason);require(no.evidence.getOppositions().stream().anyMatch(o->o.sources.size()==4),"cross-variable conflict exact FOUR original Sources");no.evidence.check(64000000,64);require(primary(f).isEmpty()&&before==f.db.getRevision(),"atomic refusal no original/revision change");}
  try(Fixture f=new Fixture(d,"Bounded")){Map<String,Integer> limits=new HashMap<>();limits.put("audit",1);long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest(RULE,limits));require(no.status==ContextSignedModelPublication.Status.INCOMPLETE,"tiny audit budget not proof or acceptance");require(primary(f).isEmpty()&&before==f.db.getRevision(),"bounded failure leaves X unchanged");}
  try(Fixture f=new Fixture(d,"Unsupported")){long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,req("!@u @v p(u)||q(v);"));require(no.status==ContextSignedModelPublication.Status.INCOMPLETE,"native positive disjunction remains unsupported");require(primary(f).isEmpty()&&before==f.db.getRevision(),"unsupported whole row not partially accepted");}
  System.out.println("MULTIVARIABLE_PUBLICATION actualConsole=true durableWholeRule=true ordinaryCrossValueFollowup=true threeVariableNativeNowSupported=true sourcedAtomicRefusal=true incompleteNoWrite=true");System.out.println("CONTEXT_MULTIVARIABLE_PUBLICATION_PASS checks="+checks);System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
